      chip.createSpan({ cls: "chip-icon", text: this.getIconForType(ctx.type) });
      chip.createSpan({ cls: "chip-label", text: ctx.summary || ctx.data });
      const removeBtn = chip.createSpan({ cls: "chip-remove", text: "\u8133" });
