    const doneFiles = getFilesByKnowledgeStatus(this.app, "done");
    const doneInfo = doneFiles.map((f) => {
      const cache = this.app.metadataCache.getFileCache(f);
      return {
        path: f.path,
        summaryPath: cache?.frontmatter?.knowledge_summary ?? null
      };
    });
